/*
 Problem: 1021. Remove Outermost Parentheses
 Language: cpp
 Runtime: 0 ms (100.00%)
 Memory: 9 MB (50.63%)
 Tags: String, Stack, Bracket Sequences
*/

class Solution {
public:
    string removeOuterParentheses(string s) {
        string ans;
        int depth = 0;

        for (char c : s) {
            if (c == '(') {
                if (depth++ > 0) ans += c;
            } else {
                if (--depth > 0) ans += c;
            }
        }

        return ans;
    }
};
